// Prisma 7 clients for the database lane, generated by scripts/test-db.sh from ./prisma/*.prisma into the git-ignored
// packages/cloudrop/.prisma-client/. They are imported by path at run time, so typechecking never needs a generated
// client; the structural type below is all the store adapter relies on (spec §7: `$queryRawUnsafe`, `$transaction`).

import { existsSync } from "node:fs";
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaPg } from "@prisma/adapter-pg";
import type { PostgresTestDatabase } from "./postgres.ts";
import type { SqliteTestDatabase } from "./sqlite.ts";

export interface PrismaTestClient {
  $queryRawUnsafe<T = unknown>(sql: string, ...values: unknown[]): Promise<T>;
  $executeRawUnsafe(sql: string, ...values: unknown[]): Promise<number>;
  $transaction<T>(run: (tx: PrismaTestClient) => Promise<T>): Promise<T>;
  $disconnect(): Promise<void>;
}

type PrismaClientClass = new (options: { adapter: PrismaPg | PrismaBetterSqlite3 }) => PrismaTestClient;

async function loadClient(dialect: "postgres" | "sqlite"): Promise<PrismaClientClass> {
  const file = new URL(`../../../.prisma-client/${dialect}/client.ts`, import.meta.url);
  if (!existsSync(file)) {
    throw new Error(
      `The Prisma test client for ${dialect} is not generated. Run the database tests with \`bun run test:db\`, which generates it.`,
    );
  }
  // The generated module's own types would tie typechecking to the generate step.
  const module = (await import(/* @vite-ignore */ file.href)) as { PrismaClient: PrismaClientClass };
  return module.PrismaClient;
}

/**
 * A Prisma client on the fixture's database: on Postgres in its schema (the URL carries the search path), on SQLite on its file (open the fixture with
 * `{ file: true }`). The caller disconnects it, registering that as soon as it has the client.
 */
export async function openPrismaClient(db: PostgresTestDatabase | SqliteTestDatabase): Promise<PrismaTestClient> {
  if (db.dialect === "postgres") {
    const PrismaClient = await loadClient("postgres");
    return new PrismaClient({ adapter: new PrismaPg({ connectionString: db.url }) });
  }
  if (!db.path) throw new Error("Prisma opens SQLite by file: call useSqliteDatabase({ file: true }).");
  const PrismaClient = await loadClient("sqlite");
  return new PrismaClient({ adapter: new PrismaBetterSqlite3({ url: `file:${db.path}` }) });
}
